public static <T> Flowable<T> traceFlowable(Context spanContext, Span span, Supplier<Flowable<T>> flowableSupplier) {
    Scope scope = spanContext.makeCurrent();
    return flowableSupplier.get().doFinally(() -> {
        scope.close();
        span.end();
    });
}

