private <T> Maybe<T> runMaybeCallbacks(Function<BasePlugin, Maybe<T>> callbackExecutor, String callbackName) {
    return Flowable.fromIterable(this.plugins).concatMapMaybe(plugin -> callbackExecutor.apply(plugin).doOnSuccess(r -> logger.debug("Plugin '{}' returned a value for callback '{}', exiting " + "early.", plugin.getName(), callbackName)).doOnError(e -> logger.error("[{}] Error during callback '{}'", plugin.getName(), callbackName, e))).firstElement();
}

