private Single<Optional<Event>> callCallback(List<Function<CallbackContext, Maybe<Content>>> agentCallbacks, InvocationContext invocationContext) {
    if (agentCallbacks == null || agentCallbacks.isEmpty()) {
        return Single.just(Optional.empty());
    }
    CallbackContext callbackContext = new CallbackContext(invocationContext, 
    null);
    return Flowable.fromIterable(agentCallbacks).concatMap(callback -> {
        Maybe<Content> maybeContent = callback.apply(callbackContext);
        return maybeContent.map(content -> {
            Event.Builder eventBuilder = Event.builder().id(Event.generateEventId()).invocationId(invocationContext.invocationId()).author(name()).branch(invocationContext.branch()).actions(callbackContext.eventActions());
            eventBuilder.content(Optional.of(content));
            invocationContext.setEndInvocation(true);
            return Optional.of(eventBuilder.build());
        }).toFlowable();
    }).firstElement().switchIfEmpty(Single.defer(() -> {
        if (callbackContext.state().hasDelta()) {
            Event.Builder eventBuilder = Event.builder().id(Event.generateEventId()).invocationId(invocationContext.invocationId()).author(name()).branch(invocationContext.branch()).actions(callbackContext.eventActions());
            return Single.just(Optional.of(eventBuilder.build()));
        } else {
            return Single.just(Optional.empty());
        }
    }));
}

private ImmutableList<Function<CallbackContext, Maybe<Content>>> beforeCallbacksToFunctions(PluginManager pluginManager, List<? extends BeforeAgentCallback> callbacks) {
    return Stream.concat(Stream.of(ctx -> pluginManager.runBeforeAgentCallback(this, ctx)), callbacks.stream().map(callback -> (Function<CallbackContext, Maybe<Content>>) callback::call)).collect(toImmutableList());
}

